import {
    ActionGroup,
    Button,
    DescriptionList,
    DescriptionListDescription,
    DescriptionListGroup,
    DescriptionListTerm,
    Form,
    PageSection,
    Spinner,
    Title,
} from '@patternfly/react-core';
import React, { useEffect, useState } from 'react';
import { Redirect } from 'react-router-dom';
import getStratosphereErrorPaths from '../../stratosphere-error-paths/get-stratosphere-error-paths';
import { getDefaultTerms, TermsFormGroup } from '../terms-form-group';
import { useChrome } from '@redhat-cloud-services/frontend-components/useChrome';
import redirectExternal from '../redirect-external';
import { getVendorOrderDetailsAsync, linkVendorOrderToAccountAsync } from '../../bff-service/bff-service';
import VendorDetails from '../../order-details/vendor/vendor-details';
import { stringifyJson } from '../../shared/utils';

function ReviewLinkOrder({ partnerId, linkToken, local, useToast }) {
    const [mergedResponse, setMergedResponse] = useState(null);
    const [redirect, setRedirect] = useState(null);
    const [hideTerms, setHideTerms] = useState(false);
    const [isAgree, setIsAgree] = useState(false);
    const [termsPdfId, setTermsPdfId] = useState(null);
    const [userOrgId, setUserOrgId] = useState(null);
    const [submitting, setSubmitting] = useState(false);
    const [fetchingResponse, setFetchingResponse] = useState(false);
    const { analytics, auth } = useChrome();
    const abortController = new AbortController();

    const errorPaths = () => getStratosphereErrorPaths(partnerId);

    const fetchUserOrgId = () => {
        auth.getUser().then((user) => {
            console.debug('Current user org_id: ', user.identity.org_id);
            setUserOrgId(user.identity.org_id);
        });
    };

    const initializeMergedResponse = (data) => {
        fetchUserOrgId();
        if (!data.terms || data.terms.length < 1) {
            setIsAgree(true);
            setHideTerms(true);
        } else {
            setTermsPdfId(getDefaultTerms(data.terms).id);
        }
        setMergedResponse(data);
    };

    const fetchMergedResponse = () => {
        if (mergedResponse === null && !fetchingResponse) {
            setFetchingResponse(true);
            getVendorOrderDetailsAsync(auth, partnerId, linkToken, abortController.signal)
              .then((res) => {
                  const { terms = [], ...restData } = res.data;
                  console.debug('Fetched Vendor merged response minus terms(Count ', terms[0].translations.length ,') : ', stringifyJson(restData));
                  if (typeof res?.data?.successful === 'boolean' && !res.data.successful) {
                      errorCallback({ response: res });
                  } else {
                      initializeMergedResponse(res.data);
                  }
              })
              .catch((error) => {
                  errorCallback(error);
              })
              .finally(() => setFetchingResponse(false));
        }
    };

    const linkOrders = () => {
        if (!submitting) {
            setSubmitting(true);
            linkVendorOrderToAccountAsync(auth, partnerId, linkToken, termsPdfId)
              .then((res) => {
                  console.debug(`Response=${res}`);
                  onLinkSuccess(res);
              })
              .catch((err) => {
                  errorCallback(err);
              })
              .finally(() => setSubmitting(false));
        }
    };

    const handleRedirect = (url) => {
        console.debug('Redirecting to: ', url);
        setRedirect(url);
    };

    const onLinkSuccess = (success) => {
        if (!success) {
            console.debug('Linking failed', errorPaths().error());
            handleRedirect(errorPaths().error());
        }

        useToast({
            key: 'confirm-link',
            message: local(`${partnerId}:toast-notification.confirm-link.success`),
            type: 'success',
        });

        analytics.track('MarketplaceConnectEvent', {
            outcome: 'link-success',
            partner: partnerId,
            locale: local.ns,
            rhAccountNumber: mergedResponse.vendorOrderSummary.accountId,
            ...mergedResponse.vendorOrderSummary,
        });

        setTimeout(() => handleRedirect(landingPage(mergedResponse)), 1000);
    };

    const landingPage = (data) => {
        let orderSummary = data?.vendorOrderSummary;
        redirectExternal(orderSummary?.landingPage || window['runConfig']['hrefConfig']);
    };

    const errorCallback = (error) => {
        console.debug('Encountered error on linking orders : ', JSON.stringify(error));
        if (error.reason === 'AbortError' || error.message === 'canceled') {
            return;
        }

        analytics.track('MarketplaceConnectEvent', {
            outcome: 'error',
            partner: partnerId,
            errorType: redirect,
        });

        const errorReason = error?.response?.data?.reason;
        const errorRedirectMap = {
            'terms_error': errorPaths().error(),
            'export_compliance_failure': errorPaths().exportError(),
            'linked_different_account': errorPaths().orderError(),
            'linked_same_account': errorPaths().orderError(),
            'missing_seller': errorPaths().tokenError(),
            'missing_token': errorPaths().tokenError(),
            'invalid_token': errorPaths().tokenError(),
            'expired_token': errorPaths().tokenError(),
        };

        handleRedirect(errorRedirectMap[errorReason] || errorPaths().systemError());
    };

    useEffect(() => {
        fetchMergedResponse();
        return () => {
            console.log('Cancelling ongoing requests...');
            abortController.abort();
        };
    }, [partnerId]);

    if (redirect) {
        return <Redirect to={redirect} />;
    }

    if (!mergedResponse) {
        return <Spinner size="xl" aria-label="Waiting on order content to load" />;
    }

    const { vendorOrderSummary, terms, linkedRedHatAccountId } = mergedResponse;

    if (linkedRedHatAccountId) {
        const info = {
            outcome: 'already-linked',
            partner: partnerId,
            errorType: redirect,
            rhAccountNumber: linkedRedHatAccountId,
        };
        analytics.track('MarketplaceConnectEvent', info);

        auth.getUser().then((user) => {
            if (user.identity.org_id === linkedRedHatAccountId) {
                console.debug('Redirecting as Order is already linked to the current user ord id : ', user.identity.org_id);
                handleRedirect(landingPage(mergedResponse));
                return;
            }

            const accountDetails = {
                orderId: vendorOrderSummary.orderDetails.vendorOrderId,
                rhAccountNumber: linkedRedHatAccountId,
            };

            console.debug('Order already linked to another org id Account details: ', accountDetails);

            const encodedData = encodeURIComponent(JSON.stringify(accountDetails));
            const redirectUrl = errorPaths().alreadyLinked() + `?data=${encodedData}`;
            handleRedirect(redirectUrl);
        });
    }

    return (
      <>
          <PageSection isFilled={true} variant="light" className="pf-u-p-2xl">
              <Title headingLevel="h1" className="pf-u-pb-xl">
                  Complete your order connection
              </Title>
              <DescriptionList
                isHorizontal
                horizontalTermWidthModifier={{
                    default: '12ch',
                    sm: '17ch',
                    md: '17ch',
                    lg: '17ch',
                    xl: '17ch',
                    '2xl': '17ch',
                }}
                className="pf-u-pb-2xl"
              >
                  <DescriptionListGroup>
                      <DescriptionListTerm>{local('review-link-account.accountNumberLabel')}</DescriptionListTerm>
                      <DescriptionListDescription>
                          {userOrgId ? userOrgId : local('review-link-account.defaultRedHatAccountNumber')}
                      </DescriptionListDescription>
                  </DescriptionListGroup>
                  {new VendorDetails(partnerId, vendorOrderSummary, local).getRows().map((row, i) => (
                    <DescriptionListGroup key={i}>
                        <DescriptionListTerm>{row.label}</DescriptionListTerm>
                        <DescriptionListDescription>{row.value}</DescriptionListDescription>
                    </DescriptionListGroup>
                  ))}
              </DescriptionList>
              <Form>
                  {
                    hideTerms || (
                      <TermsFormGroup local={local} terms={terms} onAgreeToTerms={(agree) => setIsAgree(agree)} onSelectTermsId={(id) => setTermsPdfId(id)} />
                    )
                  }
                  <ActionGroup>
                      <Button variant="primary" type="button" isDisabled={!isAgree || submitting} onClick={() => linkOrders()}>
                          {local('review-link-order.connectOrderButtonLabel')}
                      </Button>
                      <Button variant="link" href="/" component="a" style={{ paddingTop: '6px' }}>
                          {local('review-link-account.cancelButtonLabel')}
                      </Button>
                  </ActionGroup>
              </Form>
          </PageSection>
      </>
    );
}

export default ReviewLinkOrder;